import{_ as e,b as l,f as i,I as t}from"./chunks/framework.DYvp_Vyw.js";const b=JSON.parse('{"title":"安中医-计算机组成与原理-第二章","description":"","frontmatter":{"title":"安中医-计算机组成与原理-第二章","date":"2025-04-28T21:07:24.000Z","tags":["计算机组成与原理"],"head":[["meta",{"name":"descriptionx x x","content":"vitepress-theme-bluearchive Tags"}],["meta",{"name":"keywords","content":"vitepress theme bluearchive Tags"}]]},"headers":[],"relativePath":"posts/Computer-composition-002.md","filePath":"posts/Computer-composition-002.md"}'),o={name:"posts/Computer-composition-002.md"};function r(h,a,n,s,c,d){return i(),l("div",null,a[0]||(a[0]=[t('<p>根据学校的PPT自己学习后整理的笔记（实时更新） PS:为什么感觉第一二章好水啊。</p><hr><h1 id="_2-1-计算机发展史" tabindex="-1">2.1 计算机发展史 <a class="header-anchor" href="#_2-1-计算机发展史" aria-label="Permalink to &quot;2.1 计算机发展史&quot;">​</a></h1><h2 id="_2-1-1-计算机理论" tabindex="-1">2.1.1 计算机理论 <a class="header-anchor" href="#_2-1-1-计算机理论" aria-label="Permalink to &quot;2.1.1 计算机理论&quot;">​</a></h2><ul><li>图灵理论Turing</li><li>冯·诺依曼结构Von-Neumann</li><li>非冯·诺依曼结构</li><li>多机系统Mulitprocessor system</li><li>网络计算Network computing</li><li>网格技术Grid Technology</li></ul><p>科技技术发展是计算机系统的物理实现：</p><ul><li>主要是半导体技术的发展</li><li>机、磁、光、生物等技术</li><li>市场效应是主要推动作用</li></ul><blockquote><p>发展历程：单机—多机—网络计算—计算网格</p></blockquote><h2 id="_2-1-2-逻辑代数" tabindex="-1">2.1.2 逻辑代数 <a class="header-anchor" href="#_2-1-2-逻辑代数" aria-label="Permalink to &quot;2.1.2 逻辑代数&quot;">​</a></h2><p>早在1847和1854年，英国数学家布尔发表了两部重要著作《逻辑的数学分析》和《思维规律的研究》，创立了逻辑代数。逻辑代数系统采用二进制，是<strong>现代电子计算机的数学和逻辑基础</strong>。</p><h1 id="_2-1-3-计算机三原则" tabindex="-1">2.1.3 计算机三原则 <a class="header-anchor" href="#_2-1-3-计算机三原则" aria-label="Permalink to &quot;2.1.3 计算机三原则&quot;">​</a></h1><p>1939年，阿塔纳索夫提出<strong>计算机三原则</strong>:</p><ul><li>采用二进制进行运算；</li><li>采用电子技术来实现控制和运算；</li><li>采用把计算功能和存储功能相分离的结构。 1939年，阿塔纳索夫还设计并试制数字电子计算机的样机“ABC机”，但未能完工。</li></ul><p>阿塔纳索夫关于电子计算机的设计方案启发了ENIAC开发小组的莫克利，并直接影响到ENIAC的诞生。1972年美国法院判决ENIAC的专利权无效，阿塔纳索夫拥有作为第一个电子计算机方案提出者的优先权。</p><h2 id="_2-1-4-图林机" tabindex="-1">2.1.4 图林机 <a class="header-anchor" href="#_2-1-4-图林机" aria-label="Permalink to &quot;2.1.4 图林机&quot;">​</a></h2><p>现代通用数字计算机的数学模型。 1936年，24岁的英国数学家图林发表著名论文《论可计算数及其在密码问题的应用》，提出了“理想计算机”，后人称之为“图林机”。图林通过数学证明得出理论上存在“通用图林机”，这为可计算性的概念提供了严格的数学定义，图林机成为现代通用数字计算机的数学模型，它证明通用数字计算机是可以制造出来的。 图林发表于1940年的另一篇著名论文《计算机能思考吗？》，对计算机的人工智能进行了探索，并设计了著名的“图林测验”。1954年图林英年早逝，年仅42岁。</p><h2 id="_2-1-5-维纳的现代计算机设计五原则" tabindex="-1">2.1.5 维纳的现代计算机设计五原则 <a class="header-anchor" href="#_2-1-5-维纳的现代计算机设计五原则" aria-label="Permalink to &quot;2.1.5 维纳的现代计算机设计五原则&quot;">​</a></h2><p>1940年，美国科学家维纳阐述了自己对现代计算机的<strong>五点设计原则</strong>：</p><ul><li>数字式而不是模拟式；</li><li>以电子元件构成并尽量减少机械装置；</li><li>采用二进制而不是十进制；</li><li>内部存放计算表；</li><li>内部存储数据。 维纳在1948年完成了著作《控制论》，这不仅使维纳成为控制论的创始人，而且对计算机后来的发展和人工智能的研究产生了深刻的影响。</li></ul><h2 id="_2-1-6-现代电子计算机之父" tabindex="-1">2.1.6 现代电子计算机之父 <a class="header-anchor" href="#_2-1-6-现代电子计算机之父" aria-label="Permalink to &quot;2.1.6 现代电子计算机之父&quot;">​</a></h2><p>1944~1945年间，美籍匈牙利科学家冯·诺伊曼在第一台现代计算机ENIAC尚未问世时注意到其弱点，并提出一个新机型EDVAC的设计方案，其中提到了<strong>两个设想</strong>：**采用二进制和“存储程序”。这两个设想对于现代计算机至关重要，也使冯·诺伊曼成为“现代电子计算机之父”，冯·诺伊曼机体系延续至今。</p><h2 id="_2-1-7-计算机开关电路" tabindex="-1">2.1.7 计算机开关电路 <a class="header-anchor" href="#_2-1-7-计算机开关电路" aria-label="Permalink to &quot;2.1.7 计算机开关电路&quot;">​</a></h2><p>1938年，信息论的创始人、美国科学家仙农发表论文《继电器和开关电路的符号分析》，首次阐述了如何将布尔代数运用于逻辑电路，奠定了现代电子计算机开关电路的理论基础。</p><blockquote><p>1959-1964第二代计算机（晶体管）</p></blockquote><blockquote><p>1964-1970 第三代计算机（IC）</p></blockquote><blockquote><p>1970 - 第四代计算机（VLSI）</p></blockquote><blockquote><p>1971 - PC计算机的发展</p></blockquote><h1 id="_2-2-硬件技术对计算机更新换代的影响" tabindex="-1">2.2 硬件技术对计算机更新换代的影响 <a class="header-anchor" href="#_2-2-硬件技术对计算机更新换代的影响" aria-label="Permalink to &quot;2.2 硬件技术对计算机更新换代的影响&quot;">​</a></h1><p><img src="https://xfwmhxx.github.io/Blog-pic-bed/img/ca08884e85468cdb343be6ccb8225432_720.png" alt="ca08884e85468cdb343be6ccb8225432_720.png" data-fancybox="gallery"></p><h1 id="_2-3-微型计算机的出现和发展" tabindex="-1">2.3 微型计算机的出现和发展 <a class="header-anchor" href="#_2-3-微型计算机的出现和发展" aria-label="Permalink to &quot;2.3 微型计算机的出现和发展&quot;">​</a></h1><p><img src="https://xfwmhxx.github.io/Blog-pic-bed/img/68638138a999b0d425368eb2ef50b8da_720.png" alt="68638138a999b0d425368eb2ef50b8da_720.png" data-fancybox="gallery"></p><h1 id="_2-4-软件技术的兴起和发展" tabindex="-1">2.4 软件技术的兴起和发展 <a class="header-anchor" href="#_2-4-软件技术的兴起和发展" aria-label="Permalink to &quot;2.4 软件技术的兴起和发展&quot;">​</a></h1><h2 id="_2-4-1-各种语言" tabindex="-1">2.4.1 各种语言 <a class="header-anchor" href="#_2-4-1-各种语言" aria-label="Permalink to &quot;2.4.1 各种语言&quot;">​</a></h2><p>机器语言 面向机器<br> 汇编语言 面向机器<br> 高级语言 面向问题</p><ul><li>FORTRAN 科学计算和工程计算</li><li>PASCAL 结构化程序设计</li><li>C＋＋ 面向对象</li><li>Java 适应网络环境</li></ul><h1 id="_2-5-计算机的应用" tabindex="-1">2.5 计算机的应用 <a class="header-anchor" href="#_2-5-计算机的应用" aria-label="Permalink to &quot;2.5 计算机的应用&quot;">​</a></h1><h3 id="一、科学计算和数据处理" tabindex="-1">一、科学计算和数据处理 <a class="header-anchor" href="#一、科学计算和数据处理" aria-label="Permalink to &quot;一、科学计算和数据处理&quot;">​</a></h3><h3 id="二、工业控制和实时控制" tabindex="-1">二、工业控制和实时控制 <a class="header-anchor" href="#二、工业控制和实时控制" aria-label="Permalink to &quot;二、工业控制和实时控制&quot;">​</a></h3><h3 id="三、网络技术" tabindex="-1">三、网络技术 <a class="header-anchor" href="#三、网络技术" aria-label="Permalink to &quot;三、网络技术&quot;">​</a></h3><ul><li><ol><li>电子商务</li></ol></li><li><ol start="2"><li>网络教育</li></ol></li><li><ol start="3"><li>敏捷制造</li></ol></li></ul><h3 id="四、虚拟现实" tabindex="-1">四、虚拟现实 <a class="header-anchor" href="#四、虚拟现实" aria-label="Permalink to &quot;四、虚拟现实&quot;">​</a></h3><h3 id="五、办公自动化和管理信息系统" tabindex="-1">五、办公自动化和管理信息系统 <a class="header-anchor" href="#五、办公自动化和管理信息系统" aria-label="Permalink to &quot;五、办公自动化和管理信息系统&quot;">​</a></h3><h3 id="六、cad-cam-cims" tabindex="-1">六、CAD/CAM/CIMS <a class="header-anchor" href="#六、cad-cam-cims" aria-label="Permalink to &quot;六、CAD/CAM/CIMS&quot;">​</a></h3><h3 id="七、多媒体技术" tabindex="-1">七、多媒体技术 <a class="header-anchor" href="#七、多媒体技术" aria-label="Permalink to &quot;七、多媒体技术&quot;">​</a></h3><h3 id="八、人工智能" tabindex="-1">八、人工智能 <a class="header-anchor" href="#八、人工智能" aria-label="Permalink to &quot;八、人工智能&quot;">​</a></h3><h1 id="_2-6-计算机的展望" tabindex="-1">2.6 计算机的展望 <a class="header-anchor" href="#_2-6-计算机的展望" aria-label="Permalink to &quot;2.6 计算机的展望&quot;">​</a></h1><h3 id="一、计算机具有类似人脑的一些超级智能功能" tabindex="-1">一、计算机具有类似人脑的一些超级智能功能 <a class="header-anchor" href="#一、计算机具有类似人脑的一些超级智能功能" aria-label="Permalink to &quot;一、计算机具有类似人脑的一些超级智能功能&quot;">​</a></h3><p>要求计算机的速度达1015/秒</p><h3 id="二、芯片集成度的提高受以下三方面的限制" tabindex="-1">二、芯片集成度的提高受以下三方面的限制 <a class="header-anchor" href="#二、芯片集成度的提高受以下三方面的限制" aria-label="Permalink to &quot;二、芯片集成度的提高受以下三方面的限制&quot;">​</a></h3><ul><li>芯片集成度受物理极限的制约</li><li>按几何级数递增的制作成本</li><li>芯片的功耗、散热、线延迟</li></ul><h3 id="三、替代传统的硅芯片" tabindex="-1">三、替代传统的硅芯片 <a class="header-anchor" href="#三、替代传统的硅芯片" aria-label="Permalink to &quot;三、替代传统的硅芯片&quot;">​</a></h3><ol><li>光计算机： 利用光子取代电子进行运算和存储。</li><li>DNA生物计算机：通过控制DNA分子间的生化反应。</li><li>量子计算机：利用原子所具有的量子特性。</li></ol><hr>',53)]))}const p=e(o,[["render",r]]);export{b as __pageData,p as default};
